import PDFDocument from './pdf-reader/node_modules/pdfkit/js/pdfkit.es.js';
fs.mkdirSync('output/pdf',{recursive:true});
const doc=new PDFDocument({size:'A4',margins:{top:44,bottom:44,left:44,right:44},bufferPages:true,info:{Title:'LLM Reranking of Fixed CBF Candidates on FAR-Trans',Author:'Gleb Alektorov'}});
doc.registerFont('regular','C:/Windows/Fonts/arial.ttf');doc.registerFont('bold','C:/Windows/Fonts/arialbd.ttf');doc.registerFont('mono','C:/Windows/Fonts/cour.ttf');
const out=fs.createWriteStream('output/pdf/alektorov_session1_report.pdf');doc.pipe(out);
const W=doc.page.width-88, bottom=doc.page.height-44;
const clean=s=>s.replace(/\*\*/g,'').replace(/`/g,'').trim();
function room(h){if(doc.y+h>bottom)doc.addPage();}
function para(s,size=10){doc.font('regular').fontSize(size).fillColor('#19212a');const text=clean(s);const h=doc.heightOfString(text,{width:W,lineGap:1.5});room(h+5);doc.text(text,44,doc.y,{width:W,lineGap:1.5});doc.y+=5;}
function heading(s,level){const size=level===1?17:level===2?12:10.5;room(38);doc.y+=level===1?0:5;doc.font('bold').fontSize(size).fillColor('#17374d').text(clean(s),44,doc.y,{width:W});doc.y+=7;}
function table(lines){const rows=lines.filter(l=>!/^\|[- |]+\|$/.test(l)).map(l=>l.split('|').slice(1,-1).map(clean));const n=rows[0].length;const fractions=n===4?[.19,.22,.26,.33]:[.25,.38,.37];let widths=fractions.map(f=>f*W);const size=8.4,pad=5;
function row(cells,header){doc.font(header?'bold':'regular').fontSize(size);const h=Math.max(...cells.map((s,i)=>doc.heightOfString(s,{width:widths[i]-2*pad,lineGap:1})))+2*pad;const y=doc.y;let x=44;cells.forEach((s,i)=>{doc.rect(x,y,widths[i],h).fillAndStroke(header?'#e7eef3':'#ffffff','#c4ced5');doc.font(header?'bold':'regular').fontSize(size).fillColor('#19212a').text(s,x+pad,y+pad,{width:widths[i]-2*pad,lineGap:1});x+=widths[i];});doc.y=y+h;}
room(70);row(rows[0],true);for(const r of rows.slice(1)){doc.font('regular').fontSize(size);const h=Math.max(...r.map((s,i)=>doc.heightOfString(s,{width:widths[i]-2*pad,lineGap:1})))+2*pad;if(doc.y+h>bottom){doc.addPage();row(rows[0],true);}row(r,false);}doc.y+=9;}
const lines=fs.readFileSync('report.md','utf8').split(/\r?\n/);let refsPage;
for(let i=0;i<lines.length;i++){const l=lines[i];if(!l.trim())continue;if(l==='## References'){doc.addPage();refsPage=doc.bufferedPageRange().count;heading('References',2);continue;}if(l.startsWith('|')){let ls=[];while(i<lines.length&&lines[i].startsWith('|'))ls.push(lines[i++]);i--;table(ls);continue;}if(l.startsWith('```')){let ls=[];while(++i<lines.length&&!lines[i].startsWith('```'))ls.push(lines[i]);const txt=ls.join('\n');doc.font('mono').fontSize(7.2);const h=doc.heightOfString(txt,{width:W-12,lineGap:3});room(h+20);const y=doc.y;doc.rect(44,y,W,h+12).fill('#f0f3f5');doc.fillColor('#19212a').text(txt,50,y+6,{width:W-12,lineGap:3});doc.y=y+h+20;continue;}if(l.startsWith('#')){const m=l.match(/^(#+) (.*)/);heading(m[2],m[1].length);continue;}let p=l;while(i+1<lines.length&&lines[i+1].trim()&&!/^(#|\||```)/.test(lines[i+1]))p+=' '+lines[++i];para(p);}
const range=doc.bufferedPageRange();for(let i=0;i<range.count;i++){doc.switchToPage(i);doc.font('regular').fontSize(8).fillColor('#65727e').text('Gleb Alektorov | Session 1',44,doc.page.height-29,{lineBreak:false});doc.text(String(i+1),doc.page.width-60,doc.page.height-29,{lineBreak:false});}
doc.end();await new Promise(r=>out.on('finish',r));console.log(JSON.stringify({pages:range.count,referencesStart:refsPage,bodyPages:refsPage-1}));
